ctl:=population_top3000_202608_202609_v1.continuation_guard_v6('top3000-completion-20261024-root-5db48b32d103',3,1);
IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=48382 AND event='ENGINEERING_ASSIGNMENT_CLAIMED_V5' AND details->>'assignment_event_id'='47215' AND (details->>'expires_at')::timestamptz>clock_timestamp()) THEN RAISE EXCEPTION 'EXACT_CURRENT_CLAIM_REQUIRED';END IF;
SELECT jsonb_build_object('ac',to_jsonb(ac),'pc',to_jsonb(pc),'manifest',population_top3000_202608_202609_v1.population_recovery_manifest_v1(),'heldtask',(SELECT to_jsonb(t) FROM population_top3000_202608_202609_v1.pipeline_task t WHERE task_id='15a87469-6335-4bf6-b883-6c86315418e7'),'heldattempt',(SELECT to_jsonb(a) FROM population_top3000_202608_202609_v1.pipeline_attempt a WHERE attempt_id='45f6e6a5-3886-4b33-b9dc-00851c1a6b04'),'heldlease',(SELECT to_jsonb(l) FROM population_top3000_202608_202609_v1.pipeline_provider_lease l WHERE attempt_id='45f6e6a5-3886-4b33-b9dc-00851c1a6b04')) INTO before_state FROM population_top3000_202608_202609_v1.acquisition_control ac CROSS JOIN population_top3000_202608_202609_v1.pipeline_control pc WHERE ac.singleton AND pc.singleton;
BEGIN
EXECUTE $ddl$CREATE TABLE population_top3000_202608_202609_v1.ref01_receipt_spool_policy_v11(
 singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),enabled boolean NOT NULL DEFAULT false,
 worker_build text NOT NULL CHECK(worker_build='REF01_PRIVATE_SPOOL_V11'),worker_sha256 text NOT NULL CHECK(worker_sha256~'^[0-9a-f]{64}$'),
