taskj:=to_jsonb(tmpl)||jsonb_build_object('task_id',tid,'operation_key','REF01:ACQUIRE:'||rk||':SYNTHETIC_V11_ONLY','partition_key',rk,'payload',jsonb_build_object('kind','REF01_CENSUS_SOURCE_V1','request_key',rk,'request_manifest_sha256',mh),'status','LEASED','attempt_id',aid,'lease_until',clock_timestamp()+interval '5minutes','checkpoint','{}'::jsonb,'executions',1,'started_at',clock_timestamp(),'completed_at',NULL,'owner_fence',3,'stop_generation',1,'useful_committed_units',0,'cumulative_failures',0,'recheck_count',0,'resumption_condition',NULL,'blocker_code',NULL,'blocker_until',NULL);
