INSERT INTO population_top3000_202608_202609_v1.pipeline_attempt(attempt_id,task_id,execution_number,token_sha256,owner_fence,stop_generation,adapter_sha256,started_at,outcome,request_id) SELECT aid,tid,1,encode(sha256(convert_to(tok,'UTF8')),'hex'),3,1,function_sha256,clock_timestamp(),'RUNNING',900000011 FROM population_top3000_202608_202609_v1.pipeline_adapter WHERE family_id='REF01' AND stage='ACQUIRE';
