body:=jsonb_build_object('archive_key',ctx->>'archive_key','request_manifest_sha256',mh,'page_number',1,'request_url',manifest->>'first_url','next_url',NULL,'content_text',raw,'source_sha256',encode(sha256(convert_to(raw,'UTF8')),'hex'),'wire_sha256',encode(sha256(convert_to(raw,'UTF8')),'hex'),'wire_bytes',octet_length(raw),'http_status',200,'retrieved_at',clock_timestamp(),'result_count',0,'provider_request_id','SYNTHETIC_V11_ONLY','elapsed_ms',1);
