ans:=population_top3000_202608_202609_v1.ref01_spool_put_v11(aid,tok,'REF01_PRIVATE_SPOOL_V11',body);
IF ans->>'idempotent_replay' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'SPOOL_REPLAY_NOT_IDEMPOTENT';END IF;tests:=tests+1;
